import { type D1Migration, applyD1Migrations, env } from 'cloudflare:test'
import { beforeAll } from 'vitest'

/**
 * Ambient extension of the test env (vitest-pool-workers ≥0.6 types `env` as
 * the global `Cloudflare.Env`, so that is what gets merged into). The
 * integration vitest config binds the full migration list under
 * `TEST_MIGRATIONS` so test files can apply schema without re-reading the
 * SQL files at runtime.
 */
declare global {
  namespace Cloudflare {
    interface Env {
      DB: D1Database
      TEST_MIGRATIONS: D1Migration[]
    }
  }
}

beforeAll(async () => {
  await applyD1Migrations(env.DB, env.TEST_MIGRATIONS)
})

