import { app } from '../../src/app'
import { signSession } from '../../src/auth/session'
import { bumpSessionEpoch, upsertUser } from '../../src/db/queries/users'
import type { Env as WorkerEnv } from '../../src/env'

/**
 * A7 end-to-end: bumping users.session_epoch (sign-out, admin suspend)
 * must kill every outstanding session cookie at the per-request check —
 * the cookie is a 30-day stateless HMAC bearer, so this epoch match is
 * the ONLY server-side kill switch.
 */

const BASE = 'https://ctxlayer-session-epoch.test'
const SESSION_SECRET = 'session-epoch-integration-secret'

const testEnv = {
  ...(env as unknown as Record<string, unknown>),
  PUBLIC_BASE_URL: BASE,
  SESSION_COOKIE_SECRET: SESSION_SECRET
} as unknown as WorkerEnv

async function seedUser(seq: number) {
  const { user } = await upsertUser(
    testEnv,
    {
      idp: 'github',
      idpSub: `epoch-sub-${seq}`,
      email: `epoch-${seq}@test.example`,
      name: 'Epoch Test',
      avatarUrl: null
    },
    'active'
  )
  return user
}

async function getMe(cookie: string): Promise<Response> {
  return app.request(
    `${BASE}/api/me`,
    { headers: { cookie: `__Host-ctx_session=${cookie}` } },
    testEnv,
    createExecutionContext()
  )
}

describe('session epoch invalidation (A7)', () => {
  it('accepts a cookie minted under the current epoch', async () => {
    const user = await seedUser(1)
    const cookie = await signSession(
      { userId: user.id, role: user.role, epoch: user.session_epoch },
      SESSION_SECRET
    )
    const res = await getMe(cookie)
    expect(res.status).toBe(200)
    expect(((await res.json()) as { id: string }).id).toBe(user.id)
  })

  it('rejects every outstanding cookie once the epoch is bumped', async () => {
    const user = await seedUser(2)
    const cookie = await signSession(
      { userId: user.id, role: user.role, epoch: user.session_epoch },
      SESSION_SECRET
    )
    expect((await getMe(cookie)).status).toBe(200)

    await bumpSessionEpoch(testEnv, user.id)

    const rejected = await getMe(cookie)
    expect(rejected.status).toBe(401)
    // The dead cookie is also cleared so the browser drops it.
    expect(rejected.headers.get('set-cookie')).toContain('__Host-ctx_session=;')

    // A cookie minted under the NEW epoch works — invalidation is not a lockout.
    const fresh = await signSession(
      { userId: user.id, role: user.role, epoch: user.session_epoch + 1 },
      SESSION_SECRET
    )
    expect((await getMe(fresh)).status).toBe(200)
  })

  it('treats a legacy pre-epoch cookie as epoch 0 (valid until first bump)', async () => {
    const user = await seedUser(3)
    // signSession with no epoch mints epoch 0, matching the column default.
    const legacyShaped = await signSession({ userId: user.id, role: user.role }, SESSION_SECRET)
    expect((await getMe(legacyShaped)).status).toBe(200)

    await bumpSessionEpoch(testEnv, user.id)
    expect((await getMe(legacyShaped)).status).toBe(401)
  })
})

import { env } from 'cloudflare:test'
import { beforeAll, describe, expect, it } from 'vitest'
import { credentialFreshnessError } from '../../src/mcp/credential-freshness'
import {
  deleteUserCredential,
  markReauthRequired,
  upsertUserCredential
} from '../../src/db/queries/upstream-credentials'
import { createUpstream } from '../../src/db/queries/upstreams'
import { upsertUser } from '../../src/db/queries/users'
import type { Env as WorkerEnv } from '../../src/env'

/**
 * A6 against real D1: the per-call freshness gate must block a call the
 * moment the user's credential row is deleted (disconnect / admin wipe)
 * or flagged reauth-required — the session-init binding alone would keep
 * the old bearer working until the MCP session dies.
 */

const testEnv = env as unknown as WorkerEnv

let userId: string
let upstreamId: string
let conn: { id: string; slug: string; authStrategy: string }

beforeAll(async () => {
  const { user } = await upsertUser(
    testEnv,
    {
      idp: 'github',
      idpSub: 'fresh-sub-1',
      email: 'fresh-1@test.example',
      name: 'Freshness Test',
      avatarUrl: null
    },
    'active'
  )
  userId = user.id
  const upstream = await createUpstream(testEnv, {
    slug: 'up-fresh-test',
    displayName: 'Freshness Test Upstream',
    transport: 'streamable_http',
    url: 'https://fresh-upstream.test/mcp',
    authStrategy: 'user_bearer',
    authConfig: {},
    enabled: true
  })
  upstreamId = upstream.id
  conn = { id: upstreamId, slug: 'up-fresh-test', authStrategy: 'user_bearer' }
})

async function seedCredential() {
  await upsertUserCredential(testEnv, userId, upstreamId, {
    kind: 'bearer',
    ciphertext: new Uint8Array([1, 2, 3]),
    iv: new Uint8Array([4, 5, 6]),
    keyVersion: 1
  })
}

describe('credentialFreshnessError (A6)', () => {
  it('passes a present, healthy credential', async () => {
    await seedCredential()
    expect(await credentialFreshnessError(testEnv, userId, conn)).toBeNull()
  })

  it('blocks once the credential is flagged reauth-required', async () => {
    await seedCredential()
    await markReauthRequired(testEnv, userId, upstreamId)
    const msg = await credentialFreshnessError(testEnv, userId, conn)
    expect(msg).toContain('credential_revoked')
    expect(msg).toContain('re-authorization')
    expect(msg).toContain('up-fresh-test')
  })

  it('blocks once the credential row is deleted (disconnect / admin wipe)', async () => {
    await seedCredential()
    await deleteUserCredential(testEnv, userId, upstreamId)
    const msg = await credentialFreshnessError(testEnv, userId, conn)
    expect(msg).toContain('credential_revoked')
    expect(msg).toContain('disconnected')
  })

  it('never gates shared/none strategies (org-wide operator config)', async () => {
    for (const authStrategy of ['shared_bearer', 'none']) {
      expect(
        await credentialFreshnessError(testEnv, userId, { ...conn, authStrategy })
      ).toBeNull()
    }
  })
})

